// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    Log lg;

    function setUp() public { lg = new Log(); c = new X_WALLET(address(lg)); }

    // helper: is index i within History bounds? (public getter reverts when out of range)
    function inBounds(uint256 i) internal view returns (bool ok) {
        try lg.History(i) returns (address, string memory, uint256, uint256) {
            ok = true;
        } catch {
            ok = false;
        }
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, 1000 ether);
        vm.assume(inBounds(0) == false); // fresh Log: History empty (sanity, wide domain preserved)

        vm.deal(actor, amount + 1);
        vm.prank(actor);
        bool okCall;
        try c.Put{value: amount}(block.timestamp + 1) {
            okCall = true;
        } catch {
            okCall = false;
        }

        // General rule: whenever a Put call succeeds, exactly one entry is logged,
        // so index 0 must become a valid History entry afterwards.
        assertTrue(!okCall || inBounds(0), "successful Put must add a History entry");
    }
}
